import urllib.request,concurrent.futures,re
from html.parser import HTMLParser
urls=['https://cs.whu.edu.cn/','https://cs.xidian.edu.cn/','https://www.scse.uestc.edu.cn/','https://scs.bupt.edu.cn/','https://www.cs.zju.edu.cn/csen/27006/list.htm','https://cs.fudan.edu.cn/1a/fa/c24753a793338/page.htm','https://cs.nju.edu.cn/dd/ea/c1702a843242/page.htm','https://cse.seu.edu.cn/2026/0710/c49342a576431/page.htm']
class P(HTMLParser):
 def __init__(self):super().__init__();self.links=[];self.href='';self.parts=[]
 def handle_starttag(self,t,a):
  d=dict(a)
  if t=='a': self.href=d.get('href','');self.parts=[]
  if t in ['img','iframe']: self.links.append((t,str(d)))
 def handle_data(self,d):self.parts.append(d)
 def handle_endtag(self,t):
  if t=='a':self.links.append((''.join(self.parts).strip(),self.href))
def f(u):
 try:
  s=urllib.request.urlopen(u,timeout=15).read().decode('utf-8','replace');p=P();p.feed(s)
  return u,[x for x in p.links if re.search('推免|免试|招生|2027|img|iframe',x[0])]
 except Exception as e:return u,str(e)
for r in concurrent.futures.ThreadPoolExecutor().map(f,urls):print(r)
PY"

